1	/**
2	 * @license
3	 * Copyright 2026 Google LLC
4	 * SPDX-License-Identifier: Apache-2.0
5	 */
6	
7	import {Audit} from './audit.js';
8	import * as i18n from '../lib/i18n/i18n.js';
9	
10	const UIStrings = {
11	  /** Title of a Lighthouse audit that evaluates WebMCP schema validity. This descriptive title is shown to users when there are no schema validity issues. "WebMCP" stands for "Web Model Context Protocol" and should not be translated. */
12	  title: 'WebMCP schemas are valid',
13	  /** Title of a Lighthouse audit that provides detail on WebMCP schema validity. This descriptive title is shown to users when there are schema validity issues. "WebMCP" stands for "Web Model Context Protocol" and should not be translated. */
14	  failureTitle: 'WebMCP schemas are invalid',
15	  /** Description of a Lighthouse audit that tells the user why they should ensure WebMCP schemas are valid. This is displayed after a user expands the section to see more. No character length limits. "WebMCP" stands for "Web Model Context Protocol" and should not be translated. */
16	  description: 'Valid WebMCP schemas are required for AI agents to ' +
17	  ' understand and interact with tools correctly. ' +
18	      'Please fix any errors or warnings reported by the browser.',
19	  /** Header of the table column which displays the element. */
20	  columnElement: 'Element',
21	  /** Header of the table column which displays the issue. */
22	  columnIssue: 'Issue',
23	  /** Descriptive reason for why a form fails WebMCP validation due to missing `toolname` attribute. */
24	  missingToolName: 'Form level `toolname` attribute is missing. Add it to define the tool name.',
25	  /** Descriptive reason for why a form fails WebMCP validation due to missing `tooldescription` attribute. */
26	  missingToolDescription: 'Form level `tooldescription` attribute is missing. ' +
27	  'Add it to describe the tool for AI agents.',
28	  /** Descriptive reason for why a form field fails WebMCP validation due to missing `name` attribute for a required field. */
29	  missingRequiredParamName: 'Missing `name` attribute for a required field. ' +
30	  'Add it to define the parameter name.',
31	  /** Descriptive reason for why a form field fails WebMCP validation due to missing `name` attribute for an optional field. */
32	  missingOptionalParamName: 'Missing `name` attribute for an optional field. ' +
33	  'Add it to define the parameter name.',
34	  /** Descriptive reason for why a form field fails WebMCP validation due to missing description. */
35	  missingParamDescription: 'Add a description to make this form more accessible for AI agents.',
36	};
37	
38	const str_ = i18n.createIcuMessageFn(import.meta.url, UIStrings);
39	
40	class WebMcpSchemaValidity extends Audit {
41	  /**
42	   * @return {LH.Audit.Meta}
43	   */
44	  static get meta() {
45	    return {
46	      id: 'webmcp-schema-validity',
47	      title: str_(UIStrings.title),
48	      failureTitle: str_(UIStrings.failureTitle),
49	      description: str_(UIStrings.description),
50	      requiredArtifacts: ['WebMCPTools', 'WebMcpSchemaIssues'],
51	      supportedModes: ['navigation', 'snapshot'],
52	    };
53	  }
54	
55	  /**
56	   * @param {LH.Artifacts} artifacts
57	   * @return {Promise<LH.Audit.Product>}
58	   */
59	  static async audit(artifacts) {
60	    /** @enum {number} */
61	    const Severity = {
62	      ERROR: 1,
63	      WARNING: 2,
64	    };
65	
66	    /** @type {Record<string, {severity: Severity, description: LH.IcuMessage}>} */
67	    const issueConfigs = {
68	      'FormModelContextMissingToolName': {
69	        severity: Severity.ERROR,
70	        description: str_(UIStrings.missingToolName),
71	      },
72	      'FormModelContextMissingToolDescription': {
73	        severity: Severity.ERROR,
74	        description: str_(UIStrings.missingToolDescription),
75	      },
76	      'FormModelContextRequiredParameterMissingName': {
77	        severity: Severity.ERROR,
78	        description: str_(UIStrings.missingRequiredParamName),
79	      },
80	      'FormModelContextParameterMissingTitleAndDescription': {
81	        severity: Severity.WARNING,
82	        description: str_(UIStrings.missingParamDescription),
83	      },
84	      'FormModelContextParameterMissingName': {
85	        severity: Severity.WARNING,
86	        description: str_(UIStrings.missingOptionalParamName),
87	      },
88	    };
89	
90	    const rawIssues = artifacts.WebMcpSchemaIssues;
91	
92	    const uniqueIssues = [
93	      ...new Map(
94	      rawIssues.map(issue => [`${issue.violatingNodeId}_${issue.errorType}`, issue])
95	      ).values(),
96	    ];
97	    const sortedUniqueIssues = uniqueIssues.sort((a, b) => {
98	      return (issueConfigs[a.errorType]?.severity || Severity.ERROR) -
99	      (issueConfigs[b.errorType]?.severity || Severity.ERROR);
100	    });
101	    const items = sortedUniqueIssues.map(issue => {
102	      return {
103	        element: issue.nodeDetails ? Audit.makeNodeItem(issue.nodeDetails) : undefined,
104	        issue: issueConfigs[issue.errorType]?.description || '',
105	      };
106	    });
107	
108	    /** @type {LH.Audit.Details.Table['headings']} */
109	    const headings = [
110	      {key: 'element', valueType: 'node', label: str_(UIStrings.columnElement)},
111	      {key: 'issue', valueType: 'text', label: str_(UIStrings.columnIssue)},
112	    ];
113	
114	    const details = Audit.makeTableDetails(headings, items);
115	
116	    const hasErrors =
117	    sortedUniqueIssues.some(issue => issueConfigs[issue.errorType]?.severity === Severity.ERROR);
118	    const hasTools = artifacts.WebMCPTools && artifacts.WebMCPTools.length > 0;
119	    if (!hasTools && rawIssues.length === 0) {
120	      return {
121	        notApplicable: true,
122	        score: 1,
123	      };
124	    }
125	
126	    return {
127	      score: hasErrors ? 0 : (items.length > 0 ? 0.5 : 1),
128	      details: items.length > 0 ? details : undefined,
129	    };
130	  }
131	}
132	
133	export default WebMcpSchemaValidity;
134	export {UIStrings};
