12	class WebMcpSchemaIssues extends BaseGatherer {
13	  /** @type {LH.Gatherer.GathererMeta} */
14	  meta = {
15	    supportedModes: ['navigation', 'snapshot'],
16	  };
17	
18	  constructor() {
19	    super();
20	    /** @type {LH.Artifacts.WebMcpSchemaIssue[]} */
21	    this._issues = [];
22	    this._onIssueAdded = this.onIssueAdded.bind(this);
23	  }
24	
25	  /**
26	   * @param {Record<string, any>} event
27	   */
28	  onIssueAdded(event) {
29	    const issue = event.issue;
30	    if (!issue || issue.code !== 'GenericIssue') return;
31	
32	    const details = issue.details?.genericIssueDetails;
33	    if (!details) return;
34	
35	    const errorType = details.errorType;
36	    if (errorType && (
37	      errorType === 'FormModelContextMissingToolName' ||
38	      errorType === 'FormModelContextMissingToolDescription' ||
39	      errorType === 'FormModelContextRequiredParameterMissingName' ||
40	      errorType === 'FormModelContextParameterMissingTitleAndDescription' ||
41	      errorType === 'FormModelContextParameterMissingName'
42	    )) {
43	      this._issues.push(details);
44	    }
45	  }
46	
47	  /**
48	   * @param {LH.Gatherer.Context} passContext
49	   */
50	  async startInstrumentation(passContext) {
51	    const session = passContext.driver.defaultSession;
52	    session.on('Audits.issueAdded', this._onIssueAdded);
53	    await session.sendCommand('Audits.enable');
54	  }
55	
56	  /**
57	   * @param {LH.Gatherer.Context} passContext
58	   */
59	  async stopInstrumentation(passContext) {
60	    const session = passContext.driver.defaultSession;
61	    session.off('Audits.issueAdded', this._onIssueAdded);
62	  }
63	
64	  /**
65	   * @param {LH.Gatherer.Context} context
66	   * @return {Promise<LH.Artifacts.WebMcpSchemaIssue[]>}
67	   */
68	  async getArtifact(context) {
69	    const session = context.driver.defaultSession;
70	
71	    const deps = ExecutionContext.serializeDeps([
72	      pageFunctions.getNodeDetails,
73	    ]);
74	
75	    const promises = this._issues.map(async (issue) => {
76	      const processedIssue = {...issue};
77	      if (issue.violatingNodeId) {
78	        try {
79	          const objectId = await resolveNodeIdToObjectId(session, issue.violatingNodeId);
80	          if (objectId) {
81	            const response = await session.sendCommand('Runtime.callFunctionOn', {
82	              objectId,
83	              functionDeclaration: `function () {
84	                ${deps}
85	                return getNodeDetails(this);
86	              }`,
87	              returnByValue: true,
88	              awaitPromise: true,
89	            });
90	            if (response && response.result && response.result.value) {
91	              processedIssue.nodeDetails = response.result.value;
92	            }
93	          }
94	        } catch (err) {
